function onDragMove(e){
  if(!dragState) return;
  const { li, list, startX, startY } = dragState;
  if(!dragState.moved){
    if(Math.hypot(e.clientX - startX, e.clientY - startY) < 5) return;
    dragState.moved = true;
    li.classList.add("dragging");
  }
  e.preventDefault();
  // живой reorder: вставляем перетаскиваемый элемент относительно соседа под курсором
  const sibs = [...list.children].filter(x => x !== li);
  for(const sib of sibs){
    const r = sib.getBoundingClientRect();
    const mid = r.top + r.height/2;
    const liAfterSib = li.compareDocumentPosition(sib) & Node.DOCUMENT_POSITION_PRECEDING;
    if((e.clientY < mid && liAfterSib) || (e.clientY > mid && !liAfterSib)){
      list.insertBefore(li, e.clientY < mid ? sib : sib.nextSibling);
      break;
    }
  }
  refreshPositions(li.closest(".pane"));
}

